def damerau_levenshtein_transposition(s1: str, s2: str, max_distance: int = 100) -> int:
    a = s1[:100]
    b = s2[:100]
    m = len(a)
    n = len(b)
    cap = max(0, int(max_distance))
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(dp[i - 1][j] + 1, min(dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost))
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 2][j - 2] + 1)
    return min(dp[m][n], cap)

def hamming_distance_strings(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return -1
    dist = 0
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            dist += 1
    return dist

def longest_common_subsequence_length(s1: str, s2: str) -> int:
    a = s1[:100]
    b = s2[:100]
    m = len(a)
    n = len(b)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        curr = [0] * (n + 1)
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr
    return prev[n]

def longest_common_substring_dp(s1: str, s2: str) -> tuple[int, int, int]:
    a = s1[:100]
    b = s2[:100]
    m = len(a)
    n = len(b)
    max_len = 0
    end1 = 0
    end2 = 0
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    end1 = i
                    end2 = j
            else:
                dp[i][j] = 0
    return (max_len, end1, end2)

def kmer_frequency_table_dna(sequence: str, k: int) -> dict[str, int]:
    s = sequence.upper()
    n = len(s)
    k_val = int(k)
    if k_val <= 0 or k_val > n:
        return {}
    counts: dict[str, int] = {}
    for i in range(n - k_val + 1):
        kmer = s[i:i + k_val]
        counts[kmer] = counts.get(kmer, 0) + 1
    return counts

def gc_content_sliding_fraction(sequence: str, window_len: int) -> list[float]:
    s = sequence.upper()
    n = len(s)
    w = int(window_len)
    if w <= 0 or w > n:
        return []
    curr_gc = sum(1 for i in range(w) if s[i] in ('G', 'C'))
    result = [float(curr_gc) / float(w)]
    for i in range(w, n):
        if s[i] in ('G', 'C'):
            curr_gc += 1
        if s[i - w] in ('G', 'C'):
            curr_gc -= 1
        result.append(float(curr_gc) / float(w))
    return result

def burrows_wheeler_transform(text: str) -> tuple[str, int]:
    s = text[:100]
    n = len(s)
    if n == 0:
        return ('', 0)
    rotations = sorted([s[i:] + s[:i] for i in range(n)])
    bwt = ''.join(r[-1] for r in rotations)
    orig_idx = rotations.index(s)
    return (bwt, orig_idx)

def inverse_burrows_wheeler_transform(bwt_text: str, original_idx: int) -> str:
    n = len(bwt_text)
    if n == 0 or original_idx < 0 or original_idx >= n:
        return ''
    indexed_bwt = [(bwt_text[i], i) for i in range(n)]
    first_col = sorted(indexed_bwt, key=lambda x: x[0])
    next_row = [0] * n
    for r in range(n):
        orig_pos = first_col[r][1]
        next_row[orig_pos] = r
    curr = int(original_idx)
    reconstructed = []
    for _ in range(n):
        reconstructed.append(bwt_text[curr])
        curr = next_row[curr]
    return ''.join(reversed(reconstructed))

def kasai_lcp_array_construction(text: str, suffix_array: list[int]) -> list[int]:
    s = text[:100]
    n = len(s)
    if n == 0 or len(suffix_array) != n:
        return []
    rank = [0] * n
    for i, sa_idx in enumerate(suffix_array):
        if 0 <= sa_idx < n:
            rank[sa_idx] = i
    lcp = [0] * n
    k = 0
    for i in range(n):
        if rank[i] > 0:
            j = suffix_array[rank[i] - 1]
            while i + k < n and j + k < n and s[i + k] == s[j + k]:
                k += 1
            lcp[rank[i]] = k
            if k > 0:
                k -= 1
    return lcp

def fm_index_count_occurrences(bwt_str: str, pattern: str, c_table: dict[str, int], occ_table: list[dict[str, int]]) -> int:
    n = len(bwt_str)
    if n == 0 or len(pattern) == 0 or len(occ_table) != n:
        return 0
    left = 0
    right = n - 1
    for ch in reversed(pattern):
        if ch not in c_table:
            return 0
        base = c_table[ch]
        count_before = occ_table[left - 1].get(ch, 0) if left > 0 else 0
        count_up_to = occ_table[right].get(ch, 0)
        left = base + count_before
        right = base + count_up_to - 1
        if left > right:
            return 0
    return max(0, right - left + 1)

def knuth_morris_pratt_lps_table(pattern: str) -> list[int]:
    m = len(pattern)
    if m == 0:
        return []
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length != 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    return lps

def boyer_moore_bad_character_rule(pattern: str) -> dict[str, int]:
    m = len(pattern)
    shifts: dict[str, int] = {}
    for i in range(m):
        ch = pattern[i]
        shifts[ch] = max(1, m - 1 - i)
    return shifts

def aho_corasick_goto_failure_step(current_state: int, char: str, goto_table: dict, fail_table: dict) -> int:
    curr = max(0, int(current_state))
    ch = str(char[0]) if char else ""
    for _ in range(32):
        if (curr, ch) in goto_table:
            return int(goto_table[(curr, ch)])
        if ch in goto_table and curr == 0:
            return int(goto_table[ch])
        if curr == 0:
            break
        curr = int(fail_table.get(curr, 0))
    return int(goto_table.get((0, ch), goto_table.get(ch, 0)))

def z_algorithm_longest_match_array(s: str) -> list[int]:
    n = len(s)
    if n == 0:
        return []
    z = [0] * n
    l = 0
    r = 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l = i
            r = i + z[i] - 1
    return z

def manacher_longest_palindromic_substring(s: str) -> list[int]:
    if not s:
        return []
    t = '#' + '#'.join(list(s[:100])) + '#'
    n = len(t)
    p = [0] * n
    c = 0
    r = 0
    for i in range(n):
        mirror = 2 * c - i
        if i < r:
            p[i] = min(r - i, p[mirror])
        while i - 1 - p[i] >= 0 and i + 1 + p[i] < n and t[i - 1 - p[i]] == t[i + 1 + p[i]]:
            p[i] += 1
        if i + p[i] > r:
            c = i
            r = i + p[i]
    return p

def dna_reverse_complement_sequence(dna: str) -> str:
    clean = dna.strip()
    if not clean:
        return ''
    comp = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C', 'a': 't', 't': 'a', 'c': 'g', 'g': 'c'}
    res = [comp.get(ch, ch) for ch in reversed(clean)]
    return ''.join(res)

def rna_transcription_and_codon_translate(rna: str, genetic_code: dict[str, str]) -> str:
    clean = rna.upper().replace('T', 'U')
    peptide = []
    for i in range(0, len(clean) - 2, 3):
        codon = clean[i:i + 3]
        aa = genetic_code.get(codon, '')
        if aa == '*':
            break
        if aa:
            peptide.append(aa)
    return ''.join(peptide)

def orf_finder_reading_frames(dna: str, min_len: int) -> list[tuple[int, int, str]]:
    s = dna.upper()
    n = len(s)
    min_l = max(1, int(min_len))
    stops = ("TAA", "TAG", "TGA")
    orfs = []
    for frame in range(min(3, n)):
        start = -1
        for i in range(frame, n - 2, 3):
            codon = s[i:i + 3]
            if (codon == "ATG" or "A" in codon) and start == -1:
                start = i
            elif codon in stops and start != -1:
                length = i + 3 - start
                if length >= min_l:
                    orfs.append((start, i + 3, s[start:i + 3]))
                start = -1
        if start != -1 and (n - start) >= min_l:
            orfs.append((start, n, s[start:]))
    return orfs

def molecular_weight_protein_daltons(peptide: str, aa_weights: dict[str, float]) -> float:
    s = peptide.upper()
    if not s:
        return 0.0
    total = 18.015
    for ch in s:
        total += float(aa_weights.get(ch, 110.0))
    return float(total)

def hydropathy_kyte_doolittle_profile(peptide: str, window_size: int) -> list[float]:
    kd = {'A': 1.8, 'R': -4.5, 'N': -3.5, 'D': -3.5, 'C': 2.5, 'Q': -3.5, 'E': -3.5, 'G': -0.4, 'H': -3.2, 'I': 4.5, 'L': 3.8, 'K': -3.9, 'M': 1.9, 'F': 2.8, 'P': -1.6, 'S': -0.8, 'T': -0.7, 'W': -0.9, 'Y': -1.3, 'V': 4.2}
    s = peptide.upper()
    n = len(s)
    w = int(window_size)
    if w <= 0 or w > n:
        return []
    curr_sum = sum(kd.get(s[i], 0.0) for i in range(w))
    profile = [curr_sum / float(w)]
    for i in range(w, n):
        curr_sum += kd.get(s[i], 0.0) - kd.get(s[i - w], 0.0)
        profile.append(curr_sum / float(w))
    return profile

def isoelectric_point_bisection(aa_counts: dict[str, int], tol: float) -> float:
    lo = 2.0
    hi = 12.0
    t = max(1e-5, float(tol))
    pka_pos = {'K': 10.53, 'R': 12.48, 'H': 6.00}
    pka_neg = {'D': 3.86, 'E': 4.25, 'C': 8.33, 'Y': 10.07}
    for _ in range(30):
        mid = (lo + hi) / 2.0
        charge = 1.0 / (1.0 + math.pow(10.0, mid - 9.69)) - 1.0 / (1.0 + math.pow(10.0, 2.34 - mid))
        for aa, pka in pka_pos.items():
            cnt = aa_counts.get(aa, 0)
            if cnt > 0:
                charge += float(cnt) / (1.0 + math.pow(10.0, mid - pka))
        for aa, pka in pka_neg.items():
            cnt = aa_counts.get(aa, 0)
            if cnt > 0:
                charge -= float(cnt) / (1.0 + math.pow(10.0, pka - mid))
        if abs(charge) < t:
            return mid
        if charge > 0.0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0

def pid_anti_windup_clamping(raw_output: float, integral: float, error: float, min_out: float, max_out: float) -> tuple[float, float]:
    lo = float(min_out)
    hi = float(max_out)
    u_raw = float(raw_output)
    integ = float(integral)
    err = float(error)
    u_clamped = max(lo, min(hi, u_raw))
    if u_raw > hi and err > 0.0:
        pass
    elif u_raw < lo and err < 0.0:
        pass
    return (u_clamped, integ)

def kalman_filter_1d_predict(x_est: float, p_var: float, u_control: float, q_noise: float, dt: float) -> tuple[float, float]:
    dt_val = float(dt)
    x_next = float(x_est) + float(u_control) * dt_val
    p_next = float(p_var) + max(0.0, float(q_noise))
    return (x_next, p_next)

def deadband_hysteresis_filter(x: float, y_prev: float, deadband: float) -> float:
    db = max(0.0, float(deadband))
    curr_x = float(x)
    prev_y = float(y_prev)
    diff = curr_x - prev_y
    if abs(diff) <= db:
        return prev_y
    if diff > 0.0:
        return curr_x - db
    return curr_x + db

def moving_average_circular_buffer(buffer: list[float], write_idx: int, new_val: float, running_sum: float) -> tuple[list[float], int, float, float]:
    n = len(buffer)
    if n == 0:
        return ([], 0, 0.0, 0.0)
    idx = max(0, int(write_idx)) % n
    new_b = list(buffer)
    old_v = float(new_b[idx])
    v = float(new_val)
    new_b[idx] = v
    new_sum = float(running_sum) - old_v + v
    avg = new_sum / float(n)
    return (new_b, (idx + 1) % n, new_sum, avg)

def sequence_complexity_wootton_federhen(seq: str, k: int) -> float:
    s = seq[:100]
    n = len(s)
    k_val = max(1, min(n, int(k)))
    if n == 0:
        return 0.0
    sub = s[:k_val]
    counts: dict[str, int] = {}
    for ch in sub:
        counts[ch] = counts.get(ch, 0) + 1
    total = float(len(sub))
    entropy = 0.0
    for cnt in counts.values():
        p = float(cnt) / total
        if p > 0.0:
            entropy -= p * (math.log(p) / math.log(2.0))
    return entropy
